import{z as A,x as c,o as n,c as l,q as i,j as r,D as E,d as e,s as B,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Reno 与 Cubic","description":"","frontmatter":{"title":"Reno 与 Cubic","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reno-cubic.md","filePath":"cs/reno-cubic.md","lastUpdated":1791063341000}'),d={name:"cs/reno-cubic.md"};function C(p,a,u,R,m,T){const t=c("Mermaid");return n(),l("div",null,[a[2]||(a[2]=i('<h1 id="reno-与-cubic" tabindex="-1">Reno 与 Cubic <a class="header-anchor" href="#reno-与-cubic" aria-label="Permalink to &quot;Reno 与 Cubic&quot;">​</a></h1><div class="epigraph"><p>Reno 用丢包把窗口线性加减；Cubic 把窗口增长改成与真实时间相关的三次曲线，让高带宽长延迟路径不再等一个 RTT 才加一。</p><footer>—— 据 Jacobson, 1988；RFC 5681；Ha, Rhee and Xu, CUBIC；Kurose and Ross</footer></div><p><a href="/cs/tcp-congestion">上一课</a>给出慢启动、拥塞避免与 AIMD 的 <code>cwnd</code>。本课不重推「为何要有拥塞窗口」。缺口是具体响应曲线：经典 Reno（及 NewReno）把一次丢包当成减半再线性爬升；大 BDP 路径上爬升太慢。Cubic 用墙钟时间对准上次减窗点。本课不把 BBR 的瓶颈带宽估计提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/tcp-congestion">拥塞控制</a>留下 AIMD。Reno：快重传、快恢复，ssthresh 减半，避免阶段每个 RTT 约加一 MSS。窗口要加到十万 MSS 量级时，线性加太慢，链路长期欠载。Cubic：增长函数是对「距上次拥塞多久」的立方，拐点在上次窗口附近，并与 Reno 友好区做比较。缺口是<strong>同一套丢包信号下的窗口几何</strong>。</p><p><span class="marginnote">NewReno 修的是一次窗口内多丢包时快恢复的退出。Cubic 是 Linux 长期默认之一。它们仍把丢包当拥塞信号，与后课 BBR 不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Reno 族：按 RFC 5681 的阶段机更新 <code>cwnd</code>，发送速率受 <code>min(cwnd, rwnd)</code> 限制。Cubic：维护 Wmax，用墙钟计算目标窗口，再换算成每 ACK 的增量。丢包仍减窗（Cubic 减得比一半更温和）。本课不把 HyStart 全部启发式当正文。</p><p><span class="marginnote">数字实例：RTT=100ms、目标窗口 1 万 MSS 时，Reno 从减半点爬回峰值要约 5000 个 RTT——按 0.1 秒一个 RTT 算就是 8 分多钟，这期间链路大半空闲；Cubic 用时间立方起跳，几十个 RTT 就逼近 Wmax。这就是高带宽长延迟路径弃 Reno 的直接原因。</span></p>',9)),(n(),r(s,null,{default:E(()=>[B(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOSS%5B%22%E4%B8%A2%E5%8C%85%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20RENO%5B%22%E5%87%8F%E5%8D%8A%E5%90%8E%E6%AF%8F%20RTT%20%E7%BA%BF%E6%80%A7%E5%8A%A0%22%5D%0A%20%20LOSS%20--%3E%20CUBIC%5B%22%E6%97%B6%E9%97%B4%E7%AB%8B%E6%96%B9%E6%9B%B2%E7%BA%BF%E5%AF%B9%E5%87%86%20Wmax%22%5D%0A%20%20RENO%20--%3E%20SEND%5B%22min%20of%20cwnd%20%E4%B8%8E%20rwnd%22%5D%0A%20%20CUBIC%20--%3E%20SEND%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("两者都是端到端、不靠路由器显式信号（ECN 可叠加，本课不展开）。正确性仍是 TCP 可靠流；变的是共享瓶颈时的速率轨迹与友好性。假丢包（无线、"),o("a",{href:"/cs/tcp-rto"},"RTO"),e(" 估错）会让窗口无谓下降——这是丢包信号的代价，下一课换延迟/带宽观测。")],-1)),(n(),r(s,null,{default:E(()=>[B(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E6%8B%A5%E5%A1%9E%E7%82%B9%3A%20%E7%AA%97%E5%8F%A3%3DWmax%2C%20%E8%AE%B0%E4%B8%8B%E6%97%B6%E9%97%B4%22%5D%20--%3E%20T%5B%22%E7%BB%8F%E8%BF%87%E6%97%B6%E9%97%B4%20t%22%5D%0A%20%20T%20--%3E%20C%5B%22%E7%9B%AE%E6%A0%87%E7%AA%97%E5%8F%A3%20%3D%20Wmax%20%2B%20K*t%5E3%22%5D%0A%20%20C%20--%3E%20P1%5B%22t%20%E5%B0%8F%3A%20%E5%9C%A8%20Wmax%20%E4%B8%8B%E6%96%B9%E7%BC%93%E6%85%A2%E8%AF%95%E6%8E%A2%22%5D%0A%20%20C%20--%3E%20P2%5B%22t%20%E5%A4%A7%3A%20%E4%B8%89%E6%AC%A1%E9%A1%B9%E4%B8%BB%E5%AF%BC%2C%20%E5%BF%AB%E9%80%9F%E5%86%B2%E9%AB%98%22%5D%0A%20%20P2%20--%3E%20L%5B%22%E5%86%8D%E6%AC%A1%E4%B8%A2%E5%8C%85%2C%20%E6%9B%B4%E6%96%B0%20Wmax%20%E4%B8%8E%E8%B5%B7%E7%82%B9%22%5D%0A%20%20P1%20--%3E%20L%0A%20%20RENO%5B%22Reno%20%E5%AF%B9%E7%85%A7%3A%20%E6%AF%8F%E4%B8%AARTT%E5%8F%AA%E5%8A%A01%20MSS%22%5D%20--%3E%20SLOW%5B%22%E9%AB%98BDP%E8%B7%AF%E5%BE%84%E7%88%AC%E5%8D%87%E6%9E%81%E6%85%A2%22%5D%0A%20%20P2%20-.%E5%AF%B9%E6%AF%94.-%3E%20SLOW%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>这张图回答的问题是「Cubic 的窗口随时间怎么走」：以拥塞点为拐点的三次曲线——离 Wmax 越近长得越谨慎（公平、少撞墙），越过之后立方项接管快速扩张，把空闲带宽填回来。Reno 的直线则与距离无关，永远一格一格爬。</p><p><span class="marginnote">直觉类比：Reno 像下台阶后一级一级走回去，台阶越高越久；Cubic 像站在原摔跤点先伸脚试探，确认没危险后跑步冲刺回原位。两者摔的地点相同（都靠丢包发现拥塞），区别只是「爬回去的姿势」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每个操作系统的默认算法年表背完。基于测量瓶颈带宽与最小 RTT 的控制，下一课 BBR 对照。</p><p>后课默认：丢包驱动的 AIMD 有 Reno 与 Cubic 两条常用曲线。另一条路是不把丢包当唯一信号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reno：丢包减半，避免阶段线性加。</li><li>Cubic：用时间立方填满高 BDP。</li><li>测带宽与 RTT 的对照下一课。</li><li>出处：RFC 5681；CUBIC（Ha 等）；Kurose and Ross。</li></ul>',7))])}const D=A(d,[["render",C]]);export{h as __pageData,D as default};
